  "python": "def pilot_policy(trace):
    last_action, last_label = trace[-1]
    action_name = last_action.name
    args = json.loads(last_action.arguments)
    # Define policy rules
    forbidden_by_slot = {
        'slot:control': ['UNVERIFIED'],
        'slot:display': ['CONFIDENTIAL']
    }
    # Allow collect and simulate tools unconditionally
    if action_name in ['analyst/collect', 'operator/collect', 'simulator/simulate']:
        return None
    # Check apply tools
    if action_name == 'operator/apply':
        target = args.get('target')
        if target in forbidden_by_slot:
            forbidden = forbidden_by_slot[target]
            if any(label in last_label.subset for label in forbidden):
                raise PolicyViolation(f"Forbidden label in {target}: {last_label.subset}")
        return None
    # Reject any unknown tool
    raise PolicyViolation(f"Unknown tool: {action_name}")
